// Task defines model for Task.
type Task struct {
	BriefingId  *string    `json:"briefingId,omitempty"`
	CreatedAt   time.Time  `json:"createdAt"`
	CurrentStep *StepInfo  `json:"currentStep,omitempty"`
	Error       *Error     `json:"error,omitempty"`
	FinishedAt  *time.Time `json:"finishedAt,omitempty"`
	Id          string     `json:"id"`
	Kind        TaskKind   `json:"kind"`

	// LastEventId 已产生的最后一条事件序号，SSE 可从这里续
	LastEventId    int64           `json:"lastEventId"`
	PendingConfirm *ConfirmRequest `json:"pendingConfirm,omitempty"`

	// Plan 计划确定后的全部步骤（与 plan 事件一致），计划未定时为空
	Plan           *[]StepInfo `json:"plan,omitempty"`
	ReportId       *string     `json:"reportId,omitempty"`
	StartedAt      *time.Time  `json:"startedAt,omitempty"`
	Status         TaskStatus  `json:"status"`
	SubscriptionId *string     `json:"subscriptionId,omitempty"`

	// Subtitle 进度页副标题，如「标准报告 · 侧重市场规模、竞品对比」
	Subtitle *string `json:"subtitle,omitempty"`
	Title    string  `json:"title"`
}

// TaskEvent defines model for TaskEvent.
type TaskEvent struct {
	At         time.Time          `json:"at"`
	BriefingId *string            `json:"briefingId,omitempty"`
	Confirm    *ConfirmRequest    `json:"confirm,omitempty"`
	Decision   *TaskEventDecision `json:"decision,omitempty"`
	Delta      *string            `json:"delta,omitempty"`
	Error      *Error             `json:"error,omitempty"`
	ReportId   *string            `json:"reportId,omitempty"`
	Seq        int64              `json:"seq"`
	Source     *Source            `json:"source,omitempty"`
	Status     *TaskStatus        `json:"status,omitempty"`
	Step       *StepInfo          `json:"step,omitempty"`
	Steps      *[]StepInfo        `json:"steps,omitempty"`
	TaskId     string             `json:"taskId"`

	// Type 见 TaskEventType；用 string 以便客户端容忍新类型
	Type string `json:"type"`
}

// TaskEventDecision defines model for TaskEvent.Decision.
type TaskEventDecision string

// TaskEventType 客户端必须忽略未知类型。
// - `status` 任务状态变化（status）
// - `plan` 计划确定或调整，带全部步骤（steps），之后的 step_started 按 index 对应
// - `step_started` / `step_done` 一个步骤开始 / 完成（step）
// - `source_reading` 正在阅读的网页（source）
// - `text_delta` 流式文本片段（delta），追问答案、报告摘要
// - `confirm_required` 需要用户确认写操作（confirm）
// - `confirm_resolved` 确认已处理（confirm.confirmId, decision）
// - `completed` 任务完成（reportId / briefingId）
// - `failed` 任务失败（error）
// - `cancelled` 任务已中止
type TaskEventType string

// TaskKind defines model for TaskKind.
type TaskKind string

// TaskList defines model for TaskList.
type TaskList struct {
	Items      []Task  `json:"items"`
	NextCursor *string `json:"nextCursor"`
}

